    /**
     * Legacy state shape (phase / seg / lat / lng / bearing …) from an engine
     * position, so the drawing code below stays unchanged. `_pos` carries the
     * compiled segment for O(1) leg stats (zoom policy, leg bearing).
     */
    function legacyStateFrom(pos) {
      if (!pos) return null;
      const seg = pos.segment.raw;
      const base = { frac: pos.frac, seg, stopIndex: seg.stop_index ?? 0, bearing: pos.bearing, _pos: pos };
      if (pos.phase === 'intro') {
        return {
          ...base, phase: 'intro', label: seg.title || activeTrip()?.name || '',
          caption: seg.caption || '', highlights: seg.highlights || [],
          miles: seg.miles, duration_days: seg.duration_days, place_count: seg.place_count,
          stopIndex: 0, bearing: lastTravelBearing,
        };
      }
      if (pos.phase === 'outro') {
        return {
          ...base, phase: 'outro', label: 'Journey Complete',
          caption: seg.caption || '', visitedCount: seg.visited_count || 0,
          nearbyCount: seg.nearby_count || 0,
          miles: seg.miles, duration_days: seg.duration_days, place_count: seg.place_count,
          stopIndex: activeStops().length - 1, bearing: lastTravelBearing,
        };
      }
      if (pos.phase === 'dwell') {
        return {
          ...base, lat: seg.lat, lng: seg.lng, phase: 'dwell', label: seg.label || seg.to_label,
          caption: seg.caption || '', subcaption: seg.subcaption || '',
          pois: seg.pois || [], bearing: lastTravelBearing,
          is_photo: !!seg.is_photo, thumb: seg.thumb || '', thumb_full: seg.thumb_full || '', album: seg.album || '',
          photo_id: seg.photo_id || '',
          datetime: seg.datetime || seg.clock_start || '',
          stay_kind: seg.stay_kind || '',
          overnight: !!seg.overnight,
          dwell_minutes: seg.dwell_minutes,
          travelers: seg.travelers || [],
        };
      }
      if (pos.phase === 'memory') {
        return {
          ...base, lat: seg.lat, lng: seg.lng, phase: 'memory', label: seg.label,
          caption: seg.caption || '', subcaption: seg.subcaption || '',
          pois: [], bearing: lastTravelBearing,
          is_photo: true, thumb: seg.thumb || '', thumb_full: seg.thumb_full || '', album: seg.album || '',
          photo_id: seg.photo_id || '',
          datetime: seg.datetime || seg.clock_start || '',
          photo_lat: seg.photo_lat != null ? seg.photo_lat : seg.lat,
          photo_lng: seg.photo_lng != null ? seg.photo_lng : seg.lng,
          spur_miles: seg.spur_miles || 0,
          on_corridor: seg.on_corridor !== false,
          profile: seg.profile || 'driving',
        };
      }
      const path = seg.path || [];
      return {
        ...base, lat: pos.lat, lng: pos.lng, phase: 'travel', label: seg.to_label,
        path, profile: seg.profile || 'driving',
        travelers: seg.travelers || [],
      };
    }

