    // Deep links: #/trip/<id> focuses, #/trip/<id>/watch?t=<ms> plays from t. replaceState keeps
    // Back for the browser (atlas ↔ trip), not for every scrub.
    let bootRoute = parseAppRoute(location.hash);
    let routeApplying = false;
    function syncAppRoute() {
      if (routeApplying) return;
      const route = selectedId === 'all'
        ? { kind: 'home' }
        : (document.body.classList.contains('watching') || isPlaying)
          ? { kind: 'watch', id: selectedId, t: Math.round(engine.timeMs || 0) }
          : { kind: 'trip', id: selectedId };
      const next = formatAppRoute(route);
      const cur = location.hash || '#/';
      if (cur === next) return;
      // Watch time changes constantly — never push those; focus ↔ home get history entries.
      const pushable = route.kind !== 'watch' && parseAppRoute(cur).kind !== 'watch';
      try {
        if (pushable) history.pushState(null, '', next);
        else history.replaceState(null, '', next);
      } catch (_) {}
    }
    function applyAppRoute(route) {
      routeApplying = true;
      try {
        if (route.kind === 'home') {
          if (selectedId !== 'all' || document.body.classList.contains('watching')) goToAtlas();
          return;
        }
        const trip = TRIPS.find(t => t.id === route.id);
        if (!trip) { goToAtlas(); return; }
        if (selectedId !== trip.id) selectTrip(trip.id);
        if (route.kind === 'watch') {
          const startAt = route.t || 0;
          requireTripGeometry(trip).then((loaded) => {
            if (!loaded || selectedId !== loaded.id) return;
            const pb = activePlayback();
            if (!pb?.total_video_ms) return;
            if (startAt > 0 && startAt < pb.total_video_ms) {
              activeTimeline();
              engine.setTime(startAt);
              resetNavChase();
            }
            if (!isPlaying) startPlayback();
          });
        }
      } finally {
        routeApplying = false;
      }
    }
