    function mobileSheetInset() {
      if (!isJourneyBrowserOpen()) return 0;
      const panel = document.querySelector('.journey-browser-panel');
      return panel ? Math.ceil(panel.getBoundingClientRect().height + 10) : 0;
    }


    /** Trip panel geometry: side panel (desktop / landscape tablet) or bottom sheet (phone / portrait). */
    function tripPanelInset() {
      const el = document.getElementById('trip-panel');
      if (!el || selectedId === 'all' || document.body.classList.contains('watching')) return { left: 0, bottom: 0 };
      const cs = getComputedStyle(el);
      if (cs.display === 'none' || cs.visibility === 'hidden') return { left: 0, bottom: 0 };
      const r = el.getBoundingClientRect();
      const w = window.innerWidth || 1200;
      const sidePanel = r.width < w * 0.6;
      if (sidePanel) return { left: Math.ceil(r.right + 12), bottom: 0 };
      return { left: 0, bottom: Math.ceil((window.innerHeight || 800) - r.top + 8) };
    }

    function mapCameraPadding() {
      const w = map?.getContainer()?.clientWidth || window.innerWidth || 1200;
      const h = map?.getContainer()?.clientHeight || window.innerHeight || 800;
      const tier = layoutTier();
      const phone = tier === 'phone';
      const tablet = tier === 'tablet';
      const watching = document.body.classList.contains('watching');
      const browserOpen = isJourneyBrowserOpen();
      const panel = tripPanelInset();
      let bottomNeed;
      if (watching) {
        // Phone Watch: keep more map — chrome diet assumes thinner rail.
        bottomNeed = Math.min(
          phone ? 88 : tablet ? 100 : 120,
          Math.floor(h * (phone ? 0.11 : tablet ? 0.13 : 0.16)),
        );
      } else if (browserOpen && phone) {
        bottomNeed = Math.min(mobileSheetInset() + 96, Math.floor(h * 0.62));
      } else if (selectedId !== 'all') {
        // Focus: bottom sheet pushes the frame up; the side panel pushes it right (below).
        bottomNeed = panel.bottom
          ? Math.min(panel.bottom + 24, Math.floor(h * 0.6))
          : Math.min(phone ? 200 : 160, Math.floor(h * 0.2));
      } else {
        bottomNeed = atlasHomePadding().bottom;
      }
      // Brand row (~48 px) plus a pin marker riding above the route's top edge.
      const topNeed = Math.min(
        phone ? 84 : tablet ? 80 : 88,
        Math.floor(h * (phone ? 0.1 : tablet ? 0.09 : 0.1)),
      );
      const side = phone ? 16 : tablet ? 36 : 48;
      const leftNeed = panel.left ? Math.min(panel.left + 16, Math.floor(w * 0.55)) : side;
      return {
        top: topNeed,
        bottom: bottomNeed,
        left: leftNeed,
        right: Math.min(phone ? 16 : tablet ? 40 : 48, Math.floor(w * (phone ? 0.04 : tablet ? 0.05 : 0.06))),
      };
    }

