    function mapTilesReady() {
      if (!map) return true;
      try {
        if (typeof map.is3D === 'function' && map.is3D()) return true;
        if (typeof map.areTilesLoaded === 'function') return map.areTilesLoaded();
        if (typeof map.isStyleLoaded === 'function') return map.isStyleLoaded();
      } catch (_) { /* ignore */ }
      return true;
    }

