/**
 * PlaybackClock — the timeline cursor, decoupled from rendering.
 *
 * Wall time comes from `requestAnimationFrame`; the clock only knows how to
 * turn a wall delta into a timeline delta at a given rate, clamp long gaps
 * (tab switch, GC pause) and stop at the end. Everything about *what* the
 * rate should be lives in `pacing` / `buffer-governor`.
 */

export const MAX_WALL_DELTA_MS = 250;

export class PlaybackClock {
  timeMs = 0;
  totalMs = 0;
  private lastTs = 0;

  constructor(totalMs = 0) {
    this.totalMs = Math.max(0, totalMs);
  }

  setTotal(totalMs: number): void {
    this.totalMs = Math.max(0, totalMs);
    if (this.timeMs > this.totalMs) this.timeMs = this.totalMs;
  }

  /** Clamped wall ms since the previous tick (0 on the first tick after a reset). */
  wallDelta(ts: number): number {
    if (!this.lastTs) {
      this.lastTs = ts;
      return 0;
    }
    const raw = ts - this.lastTs;
    this.lastTs = ts;
    return raw > 0 ? Math.min(raw, MAX_WALL_DELTA_MS) : 0;
  }

  /** Forget the previous tick so the next frame does not count paused time. */
  resetTiming(): void {
    this.lastTs = 0;
  }

  /** Advance by `deltaMs` timeline ms; returns true when the end was reached. */
  advance(deltaMs: number): boolean {
    if (!(deltaMs > 0)) return this.timeMs >= this.totalMs && this.totalMs > 0;
    this.timeMs = Math.min(this.totalMs, this.timeMs + deltaMs);
    return this.timeMs >= this.totalMs;
  }

  seek(ms: number): void {
    const n = Number(ms);
    this.timeMs = Math.max(0, Math.min(this.totalMs, Number.isFinite(n) ? n : 0));
    this.lastTs = 0;
  }

  atEnd(): boolean {
    return this.totalMs > 0 && this.timeMs >= this.totalMs;
  }

  progress(): number {
    return this.totalMs > 0 ? Math.min(1, this.timeMs / this.totalMs) : 0;
  }
}
