/** Mapbox-compatible LngLatBounds for the Google Maps path. */

type LngLatLike = [number, number] | { lng: number; lat: number } | google.maps.LatLng;

function toLngLat(input: LngLatLike): { lng: number; lat: number } {
  if (Array.isArray(input)) return { lng: Number(input[0]), lat: Number(input[1]) };
  if (typeof (input as google.maps.LatLng).lng === "function") {
    const ll = input as google.maps.LatLng;
    return { lng: ll.lng(), lat: ll.lat() };
  }
  const o = input as { lng: number; lat: number };
  return { lng: Number(o.lng), lat: Number(o.lat) };
}

export class GoogleLngLatBounds {
  private _west = Infinity;
  private _south = Infinity;
  private _east = -Infinity;
  private _north = -Infinity;
  private _empty = true;

  extend(input: LngLatLike): this {
    const { lng, lat } = toLngLat(input);
    if (!Number.isFinite(lng) || !Number.isFinite(lat)) return this;
    if (this._empty) {
      this._west = this._east = lng;
      this._south = this._north = lat;
      this._empty = false;
      return this;
    }
    this._west = Math.min(this._west, lng);
    this._east = Math.max(this._east, lng);
    this._south = Math.min(this._south, lat);
    this._north = Math.max(this._north, lat);
    return this;
  }

  isEmpty(): boolean {
    return this._empty;
  }

  getWest(): number {
    return this._empty ? 0 : this._west;
  }
  getSouth(): number {
    return this._empty ? 0 : this._south;
  }
  getEast(): number {
    return this._empty ? 0 : this._east;
  }
  getNorth(): number {
    return this._empty ? 0 : this._north;
  }

  /** Convert to google.maps.LatLngBounds for fitBounds. */
  toGoogleBounds(gmaps: typeof google.maps): google.maps.LatLngBounds {
    return new gmaps.LatLngBounds(
      { lat: this.getSouth(), lng: this.getWest() },
      { lat: this.getNorth(), lng: this.getEast() },
    );
  }
}
