/**
 * Pure camera math for the Google Photorealistic 3D scene.
 *
 * Map3DElement has no fitBounds and thinks in {center, range, tilt, heading}
 * rather than Mapbox {center, zoom, pitch, bearing}. Everything here is
 * side-effect free so it can be unit-tested without a browser.
 */

export type WidthTier = "phone" | "tablet" | "desktop";

export type LngLatBoundsLike = {
  west: number;
  south: number;
  east: number;
  north: number;
};

export type Viewport = { width: number; height: number };

export type Padding = { top: number; right: number; bottom: number; left: number };

export type Camera3D = {
  lat: number;
  lng: number;
  range: number;
  tilt: number;
  heading: number;
  roll?: number;
};

export const EARTH_RADIUS_M = 6378137;
export const EARTH_CIRCUMFERENCE_M = 40075016.686;
/** Map3DElement default vertical field of view (degrees). */
export const DEFAULT_FOV_DEG = 35;
/** Map3D range limits we allow the director to use. */
export const RANGE_MIN_M = 220;
export const RANGE_MAX_M = 14_000_000;

const DEG = Math.PI / 180;

export function widthTier(width: number): WidthTier {
  if (width <= 640) return "phone";
  if (width <= 1180) return "tablet";
  return "desktop";
}

export function clamp(v: number, lo: number, hi: number): number {
  return Math.max(lo, Math.min(hi, v));
}

export function normalizeHeading(h: number): number {
  const n = ((h % 360) + 360) % 360;
  return n === 360 ? 0 : n;
}

/** Shortest signed angular difference target - current, in (-180, 180]. */
export function angleDiff(current: number, target: number): number {
  return ((target - current + 540) % 360) - 180;
}

export function haversineMeters(lat1: number, lng1: number, lat2: number, lng2: number): number {
  const dLat = (lat2 - lat1) * DEG;
  const dLng = (lng2 - lng1) * DEG;
  const s =
    Math.sin(dLat / 2) ** 2 +
    Math.cos(lat1 * DEG) * Math.cos(lat2 * DEG) * Math.sin(dLng / 2) ** 2;
  return 2 * EARTH_RADIUS_M * Math.asin(Math.min(1, Math.sqrt(s)));
}

export function bearingBetween(lat1: number, lng1: number, lat2: number, lng2: number): number {
  const φ1 = lat1 * DEG;
  const φ2 = lat2 * DEG;
  const Δλ = (lng2 - lng1) * DEG;
  const y = Math.sin(Δλ) * Math.cos(φ2);
  const x = Math.cos(φ1) * Math.sin(φ2) - Math.sin(φ1) * Math.cos(φ2) * Math.cos(Δλ);
  return normalizeHeading(Math.atan2(y, x) / DEG);
}

/** Destination point along a compass bearing (great-circle). Returns [lng, lat]. */
export function offsetAlongBearing(
  lng: number,
  lat: number,
  bearingDeg: number,
  meters: number,
): [number, number] {
  const δ = meters / EARTH_RADIUS_M;
  const θ = bearingDeg * DEG;
  const φ1 = lat * DEG;
  const λ1 = lng * DEG;
  const φ2 = Math.asin(Math.sin(φ1) * Math.cos(δ) + Math.cos(φ1) * Math.sin(δ) * Math.cos(θ));
  const λ2 =
    λ1 +
    Math.atan2(
      Math.sin(θ) * Math.sin(δ) * Math.cos(φ1),
      Math.cos(δ) - Math.sin(φ1) * Math.sin(φ2),
    );
  return [((λ2 / DEG + 540) % 360) - 180, φ2 / DEG];
}

// ── Springs ────────────────────────────────────────────────────────────────

export type Spring = { value: number; velocity: number };

/**
 * Critically damped spring step (no overshoot). `omega` is the natural
 * frequency in rad/s; settle time ≈ 4 / omega seconds.
 */
export function springStep(s: Spring, target: number, dt: number, omega: number): Spring {
  const h = clamp(dt, 0, 0.1);
  if (h <= 0 || !Number.isFinite(target)) return s;
  const x = s.value - target;
  const v = s.velocity;
  const e = Math.exp(-omega * h);
  const nx = (x + (v + omega * x) * h) * e;
  const nv = (v - omega * (v + omega * x) * h) * e;
  return { value: target + nx, velocity: nv };
}

/** Spring on a compass heading — takes the short way round. */
export function angleSpringStep(s: Spring, targetDeg: number, dt: number, omega: number): Spring {
  const unwrapped = s.value + angleDiff(s.value, targetDeg);
  const next = springStep(s, unwrapped, dt, omega);
  return { value: normalizeHeading(next.value), velocity: next.velocity };
}

// ── Range ↔ zoom ───────────────────────────────────────────────────────────

/** Ground meters per CSS pixel for a 512-tile scheme at a Mapbox zoom. */
export function metersPerPixel(zoom: number, lat: number): number {
  return (EARTH_CIRCUMFERENCE_M * Math.cos(lat * DEG)) / (512 * Math.pow(2, zoom));
}

/** Camera range (meters) whose untilted vertical footprint matches a Mapbox zoom. */
export function rangeFromZoom(
  zoom: number,
  lat: number,
  viewportHeight: number,
  fovDeg = DEFAULT_FOV_DEG,
): number {
  const h = Math.max(200, viewportHeight || 800);
  const groundHeight = h * metersPerPixel(zoom, lat);
  return clamp(groundHeight / (2 * Math.tan((fovDeg / 2) * DEG)), RANGE_MIN_M, RANGE_MAX_M);
}

/** Inverse of rangeFromZoom — a Mapbox-ish zoom for a Map3D range. */
export function zoomFromRange(
  range: number,
  lat: number,
  viewportHeight: number,
  fovDeg = DEFAULT_FOV_DEG,
): number {
  const h = Math.max(200, viewportHeight || 800);
  const groundHeight = 2 * Math.max(1, range) * Math.tan((fovDeg / 2) * DEG);
  const mpp = groundHeight / h;
  const z = Math.log2((EARTH_CIRCUMFERENCE_M * Math.cos(lat * DEG)) / (512 * mpp));
  return clamp(z, 0, 22);
}

// ── Bounds framing ─────────────────────────────────────────────────────────

export function boundsFromCoords(coords: Array<[number, number]>): LngLatBoundsLike | null {
  let west = Infinity;
  let east = -Infinity;
  let south = Infinity;
  let north = -Infinity;
  for (const c of coords) {
    if (!c) continue;
    const lng = Number(c[0]);
    const lat = Number(c[1]);
    if (!Number.isFinite(lng) || !Number.isFinite(lat)) continue;
    west = Math.min(west, lng);
    east = Math.max(east, lng);
    south = Math.min(south, lat);
    north = Math.max(north, lat);
  }
  if (!Number.isFinite(west) || !Number.isFinite(south)) return null;
  return { west, south, east, north };
}

export type FrameOptions = {
  tilt: number;
  heading?: number;
  fovDeg?: number;
  padding?: Partial<Padding> | number;
  minRange?: number;
  maxRange?: number;
};

function normalizePadding(p: Partial<Padding> | number | undefined, vp: Viewport): Padding {
  if (typeof p === "number") return { top: p, right: p, bottom: p, left: p };
  const pad = {
    top: Math.max(0, p?.top || 0),
    right: Math.max(0, p?.right || 0),
    bottom: Math.max(0, p?.bottom || 0),
    left: Math.max(0, p?.left || 0),
  };
  // Never let chrome eat more than 60% of either axis — fall back to proportional padding.
  const maxV = vp.height * 0.6;
  const maxH = vp.width * 0.6;
  if (pad.top + pad.bottom > maxV) {
    const k = maxV / (pad.top + pad.bottom);
    pad.top *= k;
    pad.bottom *= k;
  }
  if (pad.left + pad.right > maxH) {
    const k = maxH / (pad.left + pad.right);
    pad.left *= k;
    pad.right *= k;
  }
  return pad;
}

/**
 * Compute the Map3D camera that frames `bounds` inside the padded viewport.
 *
 * Geometry: the look-at point P is the screen centre. With tilt `t` (from
 * nadir) and vertical half-fov `a`, the ground footprint along the view axis
 * runs from h·(tan t − tan(t − aBot)) before P to h·(tan(t + aTop) − tan t)
 * after P, where h = R·cos t is the camera height. We solve h so the
 * footprint covers the bounds' N–S extent, check the E–W extent against the
 * width at the look-at distance, and shift P so the bounds sit in the middle
 * of the footprint (not at the screen centre, which would push them up).
 */
export function cameraForBounds(
  bounds: LngLatBoundsLike,
  viewport: Viewport,
  opts: FrameOptions,
): Camera3D {
  const W = Math.max(240, viewport.width || 1200);
  const H = Math.max(240, viewport.height || 800);
  const pad = normalizePadding(opts.padding, { width: W, height: H });
  const fov = opts.fovDeg ?? DEFAULT_FOV_DEG;
  const a = (fov / 2) * DEG;
  // Steep tilts blow the far edge to the horizon — framing is always ≤ 60°.
  const tiltDeg = clamp(opts.tilt, 0, 60);
  const t = tiltDeg * DEG;
  const heading = normalizeHeading(opts.heading ?? 0);

  const midLat = (bounds.north + bounds.south) / 2;
  const midLng = (bounds.east + bounds.west) / 2;
  const latM = Math.max(1, (bounds.north - bounds.south) * 111_320);
  const lngM = Math.max(1, (bounds.east - bounds.west) * 111_320 * Math.cos(midLat * DEG));

  // Ray angles for the top / bottom of the usable (padded) screen region.
  const tanA = Math.tan(a);
  const aTop = Math.atan(((H / 2 - pad.top) / (H / 2)) * tanA);
  const aBot = Math.atan(((H / 2 - pad.bottom) / (H / 2)) * tanA);
  const farK = Math.tan(Math.min(t + aTop, 89 * DEG)) - Math.tan(t);
  const nearK = Math.tan(t) - Math.tan(t - aBot);
  // Bounds extent along the view axis (N–S for heading 0, E–W for 90).
  const alongM = Math.abs(Math.cos(heading * DEG)) * latM + Math.abs(Math.sin(heading * DEG)) * lngM;
  const acrossM = Math.abs(Math.sin(heading * DEG)) * latM + Math.abs(Math.cos(heading * DEG)) * lngM;

  const hAlong = alongM / Math.max(1e-6, farK + nearK);
  const rAlong = hAlong / Math.max(0.05, Math.cos(t));
  const usableW = Math.max(W * 0.4, W - pad.left - pad.right);
  const rAcross = acrossM / Math.max(1e-6, 2 * tanA * (usableW / H));

  let range = Math.max(rAlong, rAcross);
  range = clamp(range, opts.minRange ?? RANGE_MIN_M, opts.maxRange ?? RANGE_MAX_M);

  // Shift look-at so the bounds' centre lands mid-footprint, then correct for
  // left/right chrome (in ground meters at the look-at distance).
  const h = range * Math.cos(t);
  const alongShift = (h * (farK - nearK)) / 2;
  const mpp = (2 * range * tanA) / H;
  const acrossShift = ((pad.right - pad.left) / 2) * mpp;
  let [lng, lat] = offsetAlongBearing(midLng, midLat, heading + 180, alongShift);
  [lng, lat] = offsetAlongBearing(lng, lat, heading + 90, acrossShift);

  return { lat, lng, range, tilt: tiltDeg, heading };
}

// ── Chase-cam curves ───────────────────────────────────────────────────────

export type TravelMode = "driving" | "walking" | "ferry";

/**
 * Camera range for the ground speed *as seen on screen* (meters of ground per
 * wall-clock second). Playback compresses 20 days into ~18 minutes, so a
 * 300-mile leg can cross the frame in seconds; pulling the camera back with
 * speed is what keeps motion readable instead of a blur.
 */
export function rangeForScreenSpeed(metersPerSecond: number, mode: TravelMode = "driving"): number {
  const v = Math.max(0, metersPerSecond || 0);
  // ~4 s of travel visible ahead — slightly higher floor so highway reads calmer.
  const secondsAhead = 4.0;
  const base = v * secondsAhead;
  const floor = mode === "walking" ? 200 : mode === "ferry" ? 900 : 450;
  const ceil = mode === "walking" ? 700 : mode === "ferry" ? 20_000 : 60_000;
  return clamp(base, floor, ceil);
}

/** Tilt that keeps a horizon in frame close-up and reads as an aerial when far. */
export function tiltForRange(range: number): number {
  const r = clamp(range, RANGE_MIN_M, 100_000);
  const x = Math.log10(r); // 2.34 … 5
  // 300 m → 70°, 2 km → 64°, 10 km → 56°, 60 km → 46°
  const pts: Array<[number, number]> = [
    [Math.log10(300), 70],
    [Math.log10(2000), 64],
    [Math.log10(10_000), 56],
    [Math.log10(60_000), 46],
  ];
  if (x <= pts[0][0]) return pts[0][1];
  for (let i = 1; i < pts.length; i++) {
    if (x <= pts[i][0]) {
      const [x0, y0] = pts[i - 1];
      const [x1, y1] = pts[i];
      return y0 + ((x - x0) / (x1 - x0)) * (y1 - y0);
    }
  }
  return pts[pts.length - 1][1];
}

/**
 * Ground distance from the look-at point to the screen point one sixth of the
 * viewport below centre — where the car should sit (lower third, nav style).
 */
export function lowerThirdOffset(range: number, tiltDeg: number, fovDeg = DEFAULT_FOV_DEG): number {
  const t = clamp(tiltDeg, 0, 85) * DEG;
  const a3 = Math.atan(Math.tan((fovDeg / 2) * DEG) / 3);
  const h = range * Math.cos(t);
  return Math.max(0, h * (Math.tan(t) - Math.tan(t - a3)));
}

/** Blend local road course toward the leg's overall bearing as the camera pulls back. */
export function headingBlendForRange(range: number): number {
  // 0 = follow every bend, 1 = follow the leg heading only.
  return clamp((Math.log10(Math.max(1, range)) - Math.log10(1500)) / (Math.log10(25_000) - Math.log10(1500)), 0, 1);
}

export function mixHeading(a: number, b: number, t: number): number {
  return normalizeHeading(a + angleDiff(a, b) * clamp(t, 0, 1));
}
