/**
 * Timeline compiler + O(log n) position queries.
 *
 * `compileTimeline` runs once per trip (memoised by the engine) and turns the
 * hydrated `playback.segments` into typed arrays: per-leg cumulative metres,
 * per-segment start times, the concatenated trail and the chapter landmarks.
 * `positionAt` then answers "where is the car at t" with two binary searches
 * and no allocation beyond the returned record.
 */

import { bearingBetween, clamp, haversineMeters, lerp, lowerBound, normalizeHeading } from "./math";
import { compileTrail } from "./trail";
import type {
  CompiledSegment,
  Landmark,
  LatLng,
  PlaybackPosition,
  RawPlayback,
  RawSegment,
  SegmentKind,
  Timeline,
  TravelGeometry,
} from "./types";

/** Course look-ahead (metres) — matches the legacy NAV_LOOKAHEAD_KM = 0.7. */
export const COURSE_LOOKAHEAD_M = 700;
const COURSE_SPANS = [0.25, 0.5, 0.85, 1.2];
const DEG = Math.PI / 180;

/** Stay kinds that count as an overnight / long stop chapter (mirrors diary-app STAY_MODES). */
export const STAY_MODES = new Set([
  "camp",
  "hotel",
  "airbnb",
  "car_sleep",
  "friend",
  "island",
  "home",
  "halt",
  "charge",
  "trailhead",
]);

function kindOf(type: string): SegmentKind {
  switch (type) {
    case "intro":
    case "outro":
    case "dwell":
    case "memory":
    case "travel":
      return type;
    default:
      return "dwell";
  }
}

function isPhotoMoment(seg: RawSegment | undefined): boolean {
  if (!seg) return false;
  return seg.type === "memory" || (seg.type === "dwell" && !!seg.is_photo);
}

function buildGeometry(seg: RawSegment): TravelGeometry | null {
  const path = seg.path;
  if (!Array.isArray(path) || path.length < 2) return null;
  const n = path.length;
  const coords = new Float64Array(n * 2);
  const cum = new Float64Array(n);
  let minLat = 90;
  let maxLat = -90;
  let minLng = 180;
  let maxLng = -180;
  let meters = 0;
  for (let i = 0; i < n; i++) {
    const p = path[i] as LatLng;
    const lat = Number(p[0]);
    const lng = Number(p[1]);
    coords[i * 2] = lat;
    coords[i * 2 + 1] = lng;
    if (i > 0) meters += haversineMeters(coords[i * 2 - 2], coords[i * 2 - 1], lat, lng);
    cum[i] = meters;
    if (lat < minLat) minLat = lat;
    if (lat > maxLat) maxLat = lat;
    if (lng < minLng) minLng = lng;
    if (lng > maxLng) maxLng = lng;
  }
  let realSpeedMps: number | null = null;
  if (seg.clock_start && seg.clock_end) {
    const secs = (Date.parse(String(seg.clock_end)) - Date.parse(String(seg.clock_start))) / 1000;
    // Legacy floor: 0.03 h so a mis-clocked leg does not read as supersonic.
    if (Number.isFinite(secs)) realSpeedMps = meters / Math.max(108, secs);
  }
  return {
    coords,
    cum,
    n,
    meters,
    bboxMeters: haversineMeters(minLat, minLng, maxLat, maxLng),
    legBearing: normalizeHeading(bearingBetween(coords[0], coords[1], coords[n * 2 - 2], coords[n * 2 - 1])),
    realSpeedMps,
    trailBase: 0,
  };
}

/** Interpolated `[lat, lng]` at `meters` along a leg. */
export function pointAtMeters(g: TravelGeometry, meters: number): [number, number] {
  const n = g.n;
  if (n === 1 || g.meters <= 0) return [g.coords[0], g.coords[1]];
  const m = clamp(meters, 0, g.meters);
  let i = lowerBound(g.cum, m);
  if (i >= n - 1) i = n - 2;
  const span = g.cum[i + 1] - g.cum[i];
  const t = span > 0 ? clamp((m - g.cum[i]) / span, 0, 1) : 0;
  return [lerp(g.coords[i * 2], g.coords[i * 2 + 2], t), lerp(g.coords[i * 2 + 1], g.coords[i * 2 + 3], t)];
}

/**
 * GPS-style course filter: average the unit vectors towards several look-ahead
 * points so a noisy vertex does not swing the cab. O(log n).
 */
export function courseAt(g: TravelGeometry, meters: number): number {
  if (g.n < 2 || g.meters <= 0) return g.legBearing;
  const [olat, olng] = pointAtMeters(g, meters);
  let x = 0;
  let y = 0;
  let hits = 0;
  for (const f of COURSE_SPANS) {
    // Legacy clamp: look-ahead between 0.3% and 30% of the leg.
    const span = Math.min(g.meters * 0.3, Math.max(COURSE_LOOKAHEAD_M * f, g.meters * 0.003));
    const [blat, blng] = pointAtMeters(g, Math.min(g.meters, meters + span));
    if (haversineMeters(olat, olng, blat, blng) < 20) continue;
    const br = bearingBetween(olat, olng, blat, blng) * DEG;
    x += Math.sin(br);
    y += Math.cos(br);
    hits += 1;
  }
  if (hits > 0) return normalizeHeading(Math.atan2(x, y) / DEG);
  // Arriving: keep the course of the last stretch.
  const back = Math.max(0, meters - 60);
  const [plat, plng] = pointAtMeters(g, back);
  if (haversineMeters(plat, plng, olat, olng) > 1) return normalizeHeading(bearingBetween(plat, plng, olat, olng));
  return g.legBearing;
}

function landmarkFor(seg: RawSegment, index: number, t: number): Landmark | null {
  const longStay = Number(seg.dwell_minutes) >= 45;
  const photo = isPhotoMoment(seg);
  const stayKind = String(seg.stay_kind || "").toLowerCase();
  const stay =
    seg.type === "dwell" &&
    !seg.is_photo &&
    (!!seg.overnight || (STAY_MODES.has(stayKind) && stayKind !== "charge" && stayKind !== "halt"));
  const charge = seg.type === "dwell" && !seg.is_photo && !stay && longStay;
  if (!photo && !stay && !charge) return null;
  return {
    t,
    kind: photo ? "photo" : stay ? "stay" : "charge",
    thumb: photo ? String(seg.thumb || "") : "",
    label: photo ? String(seg.album || seg.label || "Memory") : String(seg.label || (stay ? "Overnight" : "Stop")),
    stayKind: String(seg.stay_kind || ""),
    segmentIndex: index,
  };
}

export function compileTimeline(playback: RawPlayback): Timeline {
  const raws = Array.isArray(playback?.segments) ? playback.segments : [];
  const segments: CompiledSegment[] = [];
  const starts = new Float64Array(raws.length);
  const landmarks: Landmark[] = [];
  let cursor = 0;
  let firstTravelMs = -1;
  for (let i = 0; i < raws.length; i++) {
    const raw = raws[i];
    const kind = kindOf(String(raw.type));
    const durationMs = Math.max(0, Number(raw.duration_ms) || 0);
    const geometry = kind === "travel" ? buildGeometry(raw) : null;
    if (kind === "travel" && firstTravelMs < 0) firstTravelMs = cursor;
    const mark = landmarkFor(raw, i, cursor);
    if (mark) landmarks.push(mark);
    starts[i] = cursor;
    segments.push({
      index: i,
      kind,
      startMs: cursor,
      endMs: cursor + durationMs,
      durationMs,
      raw,
      geometry,
      photoNext: isPhotoMoment(raws[i + 1]),
      trailMetersBefore: 0,
      trailIndexBefore: 0,
      bearingBefore: 0,
    });
    cursor += durationMs;
  }
  const trail = compileTrail(segments);
  // Arrival state for the non-travel segments: how much trail is painted and which way the car faces.
  let trailMeters = 0;
  let trailIndex = 0;
  let bearing = 0;
  let hasBearing = false;
  for (const s of segments) {
    s.trailMetersBefore = trailMeters;
    s.trailIndexBefore = trailIndex;
    s.bearingBefore = bearing;
    const g = s.geometry;
    if (!g) continue;
    if (!hasBearing) s.bearingBefore = courseAt(g, 0);
    trailMeters = trail.cumMeters[g.trailBase] + g.meters;
    trailIndex = g.trailBase + g.n - 1;
    bearing = courseAt(g, g.meters);
    hasBearing = true;
  }
  const declared = Number(playback?.total_video_ms) || 0;
  return {
    totalMs: declared > 0 ? declared : cursor,
    segments,
    starts,
    trail,
    landmarks,
    firstTravelMs: Math.max(0, firstTravelMs),
    travelMeters: trail.totalMeters,
  };
}

/** Where is the car at `ms`? Clamped to `[0, totalMs]`. */
export function positionAt(tl: Timeline, ms: number): PlaybackPosition | null {
  const count = tl.segments.length;
  if (!count) return null;
  const t = clamp(Number.isFinite(ms) ? ms : 0, 0, tl.totalMs);
  // Largest start <= t: zero-length segments are skipped in favour of the one that follows them.
  const idx = lowerBound(tl.starts, t);
  const seg = tl.segments[idx];
  const atEnd = idx === count - 1 && t >= seg.endMs;
  const frac = atEnd ? 1 : seg.durationMs > 0 ? clamp((t - seg.startMs) / seg.durationMs, 0, 1) : 1;
  const g = seg.geometry;
  if (seg.kind === "travel" && g) {
    const meters = frac * g.meters;
    let i = lowerBound(g.cum, meters);
    if (i >= g.n - 1) i = Math.max(0, g.n - 2);
    const span = g.n > 1 ? g.cum[i + 1] - g.cum[i] : 0;
    const u = span > 0 ? clamp((meters - g.cum[i]) / span, 0, 1) : 0;
    const lat = g.n > 1 ? lerp(g.coords[i * 2], g.coords[i * 2 + 2], u) : g.coords[0];
    const lng = g.n > 1 ? lerp(g.coords[i * 2 + 1], g.coords[i * 2 + 3], u) : g.coords[1];
    return {
      timeMs: t,
      phase: "travel",
      segment: seg,
      frac,
      lat,
      lng,
      bearing: courseAt(g, meters),
      trailMeters: tl.trail.cumMeters[g.trailBase] + meters,
      trailIndex: g.trailBase + i,
      metersPerMs: seg.durationMs > 0 ? g.meters / seg.durationMs : 0,
    };
  }
  const raw = seg.raw;
  const hasPoint = typeof raw.lat === "number" && typeof raw.lng === "number";
  const isOutro = seg.kind === "outro";
  return {
    timeMs: t,
    phase: seg.kind,
    segment: seg,
    frac,
    lat: hasPoint ? (raw.lat as number) : null,
    lng: hasPoint ? (raw.lng as number) : null,
    bearing: seg.bearingBefore,
    trailMeters: isOutro ? tl.trail.totalMeters : seg.trailMetersBefore,
    trailIndex: isOutro ? Math.max(0, tl.trail.vertexCount - 1) : seg.trailIndexBefore,
    metersPerMs: 0,
  };
}

/** Segment containing `ms` (index into `tl.segments`). */
export function segmentIndexAt(tl: Timeline, ms: number): number {
  if (!tl.segments.length) return -1;
  return lowerBound(tl.starts, clamp(ms, 0, tl.totalMs));
}

/** Next / previous landmark relative to `ms` (`near` = tolerance so "prev" skips the current one). */
export function landmarkFrom(tl: Timeline, ms: number, dir: 1 | -1, near = 400): Landmark | null {
  const marks = tl.landmarks;
  if (!marks.length) return null;
  if (dir > 0) return marks.find((m) => m.t > ms + near) || null;
  for (let i = marks.length - 1; i >= 0; i--) if (marks[i].t < ms - near) return marks[i];
  return null;
}
